
(()=>{const nav=document.querySelector('#primary-navigation'),menu=document.querySelector('.menu-toggle'),platform=document.querySelector('.nav-platform-label');const closeNav=()=>{menu?.setAttribute('aria-expanded','false');nav?.setAttribute('data-open','false')};menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.setAttribute('data-open',String(open))});nav?.addEventListener('click',e=>{if(e.target.closest('a'))closeNav()});platform?.addEventListener('click',()=>platform.setAttribute('aria-expanded',String(platform.getAttribute('aria-expanded')!=='true')));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeNav();platform?.setAttribute('aria-expanded','false')}});const here=location.pathname.split('/').pop()||'index.html';document.querySelectorAll('nav a').forEach(a=>{if(a.getAttribute('href')===here)a.setAttribute('aria-current','page')});const dialog=document.createElement('dialog');dialog.className='screen-dialog';dialog.setAttribute('aria-label','Platform screenshot');const close=document.createElement('button');close.type='button';close.textContent='Close';const caption=document.createElement('p');const image=document.createElement('img');dialog.append(close,caption,image);document.body.append(dialog);close.addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});document.querySelectorAll('.enlarge-screen').forEach(link=>link.addEventListener('click',e=>{if(typeof dialog.showModal!=='function')return;e.preventDefault();image.src=link.href;image.alt=link.querySelector('img').alt;caption.textContent=image.alt;dialog.showModal()}));})();
